void handle_timer_callback(struct snd_timer_instance *timeri, int event,
                           struct timespec *tstamp, unsigned long resolution)
{
    if (event < 0 || event >= SNDRV_TIMER_EVENT_MAX)
        return;

    if (!timeri->read_filter[event])
        return;

    if (snd_timer_read_available(timeri) < 0)
        return;

    struct snd_timer_read read;
    read.event.type = SNDRV_TIMER_EVENT;
    read.event.event = event;
    read.event.tstamp = *tstamp;
    read.resolution = resolution;

    snd_timer_queue_lock(timeri);
    snd_timer_queue_append(timeri, &read);
    snd_timer_queue_unlock(timeri);

    wake_up(&timeri->wait_queue);
}

void handle_timer_callback(struct snd_timer_instance *timeri, int event,
                           struct timespec *tstamp, unsigned long resolution)
{
    if (event < 0 || event >= SND_TIMER_EVENT_MAX)
        return;

    if (!timeri->client || !timeri->client->read)
        return;

    if (timeri->filter & (1 << event)) {
        struct snd_timer_read read;
        read.event = event;
        read.tstamp = *tstamp;
        read.resolution = resolution;

        spin_lock(&timeri->queue_lock);
        list_add_tail(&read.list, &timeri->queue);
        spin_unlock(&timeri->queue_lock);

        wake_up_interruptible(&timeri->wait_queue);
    }
}

void handle_timer_callback(struct snd_timer_instance *timeri, int event, struct timespec *tstamp, unsigned long resolution)
{
    if (event < 0 || event >= SNDRV_TIMER_EVENT_MAX)
        return;

    if (tstamp)
        memcpy(&timeri->timestamp, tstamp, sizeof(*tstamp));

    if (!(timeri->filter & (1 << event)))
        return;

    if (timeri->qlock)
        return;

    struct snd_timer_read read;
    read.event = event;
    read.tstamp = timeri->timestamp;

    spin_lock_irq(&timeri->lock);
    snd_timer_enqueue(timeri, &read);
    spin_unlock_irq(&timeri->lock);

    wake_up(&timeri->wait_queue);
}

void handle_sound_timer_callback(struct snd_timer_instance *timeri, int event,
                                 struct timespec *tstamp, unsigned long resolution)
{
    if (event < 0 || event >= SNDRV_TIMER_EVENT_MAX)
        return;

    if (timeri->filter & (1 << event)) {
        struct snd_timer_read *tr;
        struct snd_timer_queue *tq = timeri->queue;
        int nonblock = timeri->nonblock;

        if (tq == NULL)
            return;

        tr = kmalloc(sizeof(*tr), GFP_KERNEL);
        if (!tr)
            return;

        tr->event = event;
        tr->resolution = resolution;
        tr->timestamp = *tstamp;

        spin_lock_irq(&tq->lock);
        list_add_tail(&tr->list, &tq->reads);
        spin_unlock_irq(&tq->lock);

        wake_up_interruptible(&tq->wait);
        if (!nonblock)
            snd_timer_wakeup(timeri);
    }
}

void handle_timer_callback(struct snd_timer_instance *timeri, int event, struct timespec *tstamp, unsigned long resolution) {
    if (event < 0 || event >= SND_TIMER_EVENT_MAX)
        return;

    if (!timeri->private_data || !timeri->queue)
        return;

    if ((timeri->filter & (1 << event)) == 0)
        return;

    struct snd_timer_read *tr = (struct snd_timer_read *)timeri->private_data;
    tr->resolution = resolution;
    tr->timestamp = *tstamp;
    tr->event = event;

    snd_timer_queue_lock(timeri->queue);
    list_add_tail(&tr->list, &timeri->queue->reads);
    snd_timer_queue_unlock(timeri->queue);

    wake_up(&timeri->queue->wait);
}
